 function fieldError(el){if(!fieldActive(el))return "";const val=el.type==="checkbox"?el.checked:el.value; if(isRequired(el)&&(!val||String(val).trim()===""))return "This field is required.";if(el.type==="email"&&val&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val))return "Enter a valid email address.";if(el.minLength>0&&val&&String(val).trim().length<el.minLength)return `Enter at least ${el.minLength} characters.`;if(el.name==="applicantContact"&&val&&!/^\d{11}$/.test(val))return "Enter exactly 11 digits.";return "";}
