 function validateFile(file){if(!file)return "";const ext=(file.name.split(".").pop()||"").toLowerCase();if(!["pdf","jpg","jpeg","png"].includes(ext))return "Unsupported file format. Choose PDF, JPG, or PNG.";if(file.size>5*1024*1024)return "File is larger than 5 MB.";if(file.size===0)return "The selected file is empty.";if(file.type&&!["application/pdf","image/jpeg","image/png"].includes(file.type))return "The file type does not match an accepted format.";if(fileCheckPending)return "Checking the file contents…";if(fileSignatureError)return fileSignatureError;return "";}
 function updateChecklist(){const items=checklistItems(),done=items.filter(x=>x.complete).length,total=items.length,pct=total?Math.round(done/total*100):100;$("#request-checklist").innerHTML=items.map(x=>`<div class="check-row ${x.complete?"is-complete":""}"><span>${x.complete?"✓":"○"}</span><span>${esc(x.label)}</span><strong>${x.complete?"Complete":"Incomplete"}</strong></div>`).join("")||`<p class="field-hint">No additional checklist items apply.</p>`;$("#checklist-count").textContent=`${done} of ${total} requirements complete`;$("#request-progress-label").textContent=pct+"%";$("#request-progress-bar").style.width=pct+"%";translateDOM(wrap);return {items,done,total}}
