 form.addEventListener("input",()=>{validateAll()});form.addEventListener("change",()=>{toggleBranch();validateAll()});
 $("#request-attachment").addEventListener("change",e=>{$("#request-file-name").textContent=e.target.files?.[0]?.name||"No file chosen";selectedFile=e.target.files?.[0]||null;fileSignatureError="";fileCheckPending=false;const file=selectedFile;const err=file?validateFile(file):"";$("#request-attachment-info").textContent=file?(err||`${file.name} · ${Math.max(1,Math.round(file.size/1024))} KB · Selected / Ready for Submission`):"Not Uploaded";$("#request-attachment-info").classList.toggle("has-error",!!err);$("#remove-request-attachment").hidden=!file;validateAll();if(file&&!err){fileCheckPending=true;$("#request-attachment-info").textContent="Checking file contents…";validateAll();file.slice(0,12).arrayBuffer().then(buf=>{if(selectedFile!==file)return;const bytes=new Uint8Array(buf),ext=(file.name.split(".").pop()||"").toLowerCase();const pdf=bytes[0]===37&&bytes[1]===80&&bytes[2]===68&&bytes[3]===70;const png=bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71&&bytes[4]===13&&bytes[5]===10&&bytes[6]===26&&bytes[7]===10;const jpg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;const valid=(ext==="pdf"&&pdf)||(["jpg","jpeg"].includes(ext)&&jpg)||(ext==="png"&&png);fileCheckPending=false;fileSignatureError=valid?"":"The file contents do not match its PDF, JPG, or PNG extension.";$("#request-attachment-info").textContent=validateFile(file)||`${file.name} · ${Math.max(1,Math.round(file.size/1024))} KB · Selected / Ready for Submission`;$("#request-attachment-info").classList.toggle("has-error",!!fileSignatureError);validateAll()}).catch(()=>{fileCheckPending=false;fileSignatureError="Could not inspect the selected file contents.";validateAll()})}});
