function renderApp(){const u=DigiStore.user();if(!u){renderAuth();return}const d=DigiStore.get();if(u.role==="admin"&&["services","digital-id"].includes(page))page="dashboard";let title="Dashboard",sub="Manage your digital community services",content="";switch(page){case"dashboard":title=u.role==="admin"?"Administrator overview":"Resident dashboard";content=dashboard(u,d);break;case"services":title="Browse services";content=`<div class="page-title"><h2>Community services</h2><p>Review the available services and start a request.</p></div>${serviceCards()}`;break;case"requests":title=u.role==="admin"?"Service requests":"My requests";content=requestsPage(u,d);break;case"profile":title="My profile";content=profilePage(u);break;case"digital-id":title="Digital ID";content=idPage(u);break;case"announcements":title="Announcements";content=announcementsPage(u,d);break;case"residents":title="Residents";content=residentsPage(d);break;case"manage-admins":title="Manage Admins";content=manageAdminsPage(d);break;case"audit":title="Activity log";content=auditPage(d);break;default:page="dashboard";return renderApp()}shell(content,title,sub);bindPage(u);if(page==="requests"){const pending=uiPrefs()["pending_request_"+u.id];if(pending){saveUIPref("pending_request_"+u.id,"");if(d.requests.some(x=>x.id===pending&&(u.role==="admin"||x.userId===u.id)))requestModal(pending)}}}
